<div class="banner"><h1><?= icon('users') ?> Customer Dashboard</h1><p>Welcome, <?= e($cust['full_name']) ?>! · <?= e($cust['address']) ?></p></div>
<div class="cards three"><div class="card-stat c-blue"><?= icon('gauge') ?>Meter No.<b><?= e($cust['meter_no']) ?></b><?= $last ? '<small>Latest reading ' . e($last['meter_value']) . ' · ' . e($last['units_used']) . ' units used</small>' : '' ?></div>
<div class="card-stat c-green"><?= icon('file') ?>Current Bill<b><?= $now ? e(money($now['total_amount'] - $now['amount_paid'])) : '—' ?></b><?= $now ? badge($now['status']) : '' ?></div><div class="card-stat c-purple"><?= icon('calendar') ?>Due Date<b><?= $now ? e($now['due_date']) : '—' ?></b></div></div>
