<?php foreach (array_slice($bills, 0, 6) as $b): ?><tr><td><?= e($b['billing_month']) ?></td><td><?= e(money($b['total_amount'])) ?></td><td><?= badge($b['status']) ?></td><td><a class="btn sm <?= in_array($b['status'], ['Unpaid', 'Partially Paid'], true) ? '' : 'ghost' ?>" href="<?= url('bills/show', ['id' => $b['bill_id']]) ?>"><?= in_array($b['status'], ['Unpaid', 'Partially Paid'], true) ? 'Pay Now' : 'View' ?></a></td></tr><?php endforeach; ?>
